from fastapi import FastAPI
from pydantic import BaseModel
import json

class ModelA(BaseModel):
    a: str

class ModelB(BaseModel):
    b: str

app = FastAPI(
    responses={
        500: {
            'model': ModelA | ModelB,
            'content': {"application/json": {
                'examples': {"Case A": {"value": "a"}}
            }}
        }
    }
)

@app.get('/route1')
def route1():
    return "test"

@app.get('/route2')
def route2():
    return "test"

@app.get('/route3')
def route3():
    return "test"

if __name__ == "__main__":
    openapi_schema = app.openapi()
    responses_500_route1 = openapi_schema["paths"]["/route1"]["get"]["responses"]["500"]
    any_of = responses_500_route1["content"]["application/json"]["schema"]["anyOf"]
    print(f"Number of anyOf elements: {len(any_of)}")
    print(json.dumps(any_of, indent=2))

    # Check if it's duplicated
    if len(any_of) > 2:
        print("BUG REPRODUCED: anyOf elements are duplicated")
    else:
        print("BUG NOT REPRODUCED")

